const key='sums-pos-demo-v1';
const seedProducts=[['Kopi Susu Signature',28000,65,'Minuman','☕'],['Iced Matcha Latte',34000,28,'Minuman','🍵'],['Croissant Butter',26000,18,'Pastry','🥐'],['Nasi Ayam Sambal',45000,36,'Makanan','🍛'],['Chocolate Cake',38000,12,'Pastry','🍰'],['Sparkling Lemon',24000,50,'Minuman','🍋']].map(([name,price,stock,category,icon])=>({id:crypto.randomUUID(),name,price,stock,category,icon,active:true}));
let state;
try{state=JSON.parse(localStorage.getItem(key))}catch{}
if(!state?.businesses?.length){state={businesses:[{id:crypto.randomUUID(),name:'Aruna Coffee & Kitchen',category:'Cafe & Restaurant',accent:'#087f6c',products:seedProducts,orders:[]}],current:null};state.current=state.businesses[0].id;for(let d=6;d>=0;d--){for(let n=0;n<3;n++){const p=seedProducts[(d+n)%6],date=new Date();date.setDate(date.getDate()-d);date.setHours(8+n,12,0,0);state.businesses[0].orders.push({id:crypto.randomUUID(),number:`DEMO-${d}${n}`,createdAt:date.toISOString(),paidAt:date.toISOString(),status:'paid',method:'cash',type:'takeaway',table:'',note:'Data contoh',lines:[{id:p.id,name:p.name,price:p.price,qty:n+1}],total:p.price*(n+1),tendered:p.price*(n+1),change:0})}}}
let stopLoginViewport=()=>{};
let surface=loginPortal(location.search);
let cloud=false,busy=false,requestId=crypto.randomUUID(),cloudStamp='',role='owner',page='dashboard',cart=[],query='',filter='all',reportDays=1;
const business=()=>state.businesses.find(b=>b.id===state.current)||state.businesses[0];
let selectedRange=null,rangeData=null,rangeFlight='',rangeError='',rangeGeneration=0;
function currentRange(){return selectedRange||dateRange(reportDays,business().timezone||'Asia/Makassar')}
function rangeKey(){const r=currentRange();return business().id+':'+r.from+':'+r.to+':'+filter}
function selectedSales(){const r=currentRange();return cloud?(rangeData?.key===rangeKey()?rangeData.orders:[]):business().orders.filter(o=>o.status==='paid'&&inDateRange(o.paidAt,r,business().timezone||'Asia/Makassar'))}
function rangeToolbar(){const r=currentRange();return `<form id="sales-date-filter" class="toolbar sales-date-filter"><label>From<input type="date" name="from" required value="${r.from}"></label><label>To<input type="date" name="to" required value="${r.to}"></label><button class="primary">Apply dates</button><select id="period" aria-label="Quick date range"><option value="custom" ${selectedRange?'selected':''}>Custom dates</option>${[[1,'Today'],[7,'Last 7 days'],[30,'Last 30 days']].map(([d,t])=>`<option value="${d}" ${!selectedRange&&reportDays===d?'selected':''}>${t}</option>`).join('')}</select></form>`}
function salesInsights(){if(cloud&&rangeData?.key!==rangeKey())return `<section class="card empty">${rangeError?esc(rangeError)+' <button id="retry-sales">Retry</button>':'Loading sales for selected dates…'}</section>`;return insightsHTML(cloud?{top:rangeData.insights.top,unsold:rangeData.insights.unsold.filter(p=>filter==='all'||p.category_id===filter)}:productPerformance(business().products,selectedSales(),filter),esc,money)}
async function ensureSalesRange(){if(!cloud||!['dashboard','reports'].includes(page)||page==='reports'&&reportView!=='sales')return;const key=rangeKey();if(rangeData?.key===key||rangeFlight===key||rangeError)return;rangeFlight=key;const generation=++rangeGeneration,b=business(),r=currentRange(),end=new Date(r.to+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);try{const [orders,insights]=await Promise.all([api.loadSalesRange(b.id,midnightUTC(r.from,b.timezone),midnightUTC(end.toISOString().slice(0,10),b.timezone)),api.rpc('pos_product_performance',{b:b.id,p_from:r.from,p_to:r.to,p_category:filter==='all'?null:filter})]);if(generation!==rangeGeneration||key!==rangeKey())return;rangeData={key,orders,insights};rangeFlight='';render();}catch(e){if(generation!==rangeGeneration)return;rangeFlight='';rangeError=e.message;render();}}

let tableChoice=null,guestName='',guestConfirmed=false,orderType='dinein',basketOpen=false,draftNote='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const restaurant=restaurantUI({business,esc,money,modal,api,cloudAction,toast,render,print:renderPrint,can:p=>can(p)});
const owner=ownerUI({business,state:()=>state,esc,api,modal,render,cloudAction,refreshCloud,toast,isOwner:()=>role==='owner',go:p=>{page=p},logout:async()=>{await api.logout();cloud=false;cart=[];resetGuest();authScreen()}});
const refunds=refundUI({business,esc,money,modal,cloudAction,api,render,can:p=>can(p),owner:()=>role==='owner',exportCsv:downloadCsv});
