async function cloudAction(fn){if(!navigator.onLine){toast('Koneksi internet diperlukan untuk menyimpan perubahan');return false}if(busy)return false;busy=true;try{await fn();await refreshCloud();toast('Perubahan tersimpan di server');return true}catch(e){toast(e.message);return false}finally{busy=false}}
async function refreshCloud(){try{const list=await api.loadBusinesses();if(!list.length){state={businesses:[],current:null};onboarding();return}const current=state.current&&list.some(b=>b.id===state.current)?state.current:list[0].id;const data=await api.loadBusiness(current);state={businesses:list,current};Object.assign(business(),data);rangeData=null;rangeFlight='';rangeError='';rangeGeneration++;role=business().membership.role;if(['cashier','waiter'].includes(role)){surface='pos';const u=new URL(location.href);u.searchParams.set('app','pos');history.replaceState(null,'',u)}const context=api.getSession().user.id+':'+current+':'+role+':'+business().restaurant_mode+':'+business().waiter_enabled;if(surface==='pos'&&(posContext!==context||!routes().includes(page)))page=posHome(role,business());posContext=context;cloudStamp=JSON.stringify(data);startLive();render()}catch(e){toast(e.message);if(!api.getSession()){cloud=false;authScreen()}}}
function authScreen(signupMode=false){stopLoginViewport();stopLoginViewport=()=>{};const staff=surface==='pos';if(staff)signupMode=false;document.querySelector('meta[name=viewport]').content=staff?'width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover,interactive-widget=resizes-content':'width=device-width,initial-scale=1,viewport-fit=cover';stopLive();document.body.classList.remove('pos-app-shell','owner-office');document.body.classList.toggle('pos-login-shell',staff);document.title=staff?'Staff login · SUMS POS':'Owner login · SUMS POS';document.querySelector('#app').innerHTML=loginMarkup(surface,signupMode);if(staff)stopLoginViewport=bindLoginViewport();localize(document.querySelector('#app'));document.querySelector('#switchauth')?.addEventListener('click',()=>authScreen(!signupMode));document.querySelector('#show-password')?.addEventListener('click',e=>{const input=document.querySelector('#authform [name=password]'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=tr(show?'Hide':'Show');e.currentTarget.setAttribute('aria-pressed',String(show));e.currentTarget.setAttribute('aria-label',tr(show?'Hide password':'Show password'))});document.querySelector('#demo')?.addEventListener('click',()=>{cloud=false;role='owner';page='dashboard';try{state=JSON.parse(localStorage.getItem(key))}catch{}render()});document.querySelector('#authform').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('.primary'),status=document.querySelector('#authstatus');btn.disabled=true;status.textContent=tr('Connecting…');try{if(signupMode){await api.signup(f.get('email').trim(),f.get('password'));if(!api.getSession()){status.textContent=tr('Check your email to confirm your account, then sign in.');e.target.reset();return}}else await api.login(f.get('email').trim(),f.get('password'),staff?'pos':'office');cloud=true;cart=[];resetGuest();posContext='';await refreshCloud()}catch(err){status.textContent=tr(err.message)}finally{btn.disabled=false}}}

function onboarding(){document.querySelector('#app').innerHTML=`<main class="auth"><section class="authstory"><div class="brand">${brandLogo()}</div><h1>Workspace untuk<br>bisnis Anda.</h1><p>Mulai dengan identitas bisnis. Katalog dapat ditambahkan setelah workspace dibuat.</p></section><section class="authform"><div class="eyebrow">LET'S GET STARTED</div><h1>Siapkan bisnis Anda</h1><form id="onboard"><label>Nama bisnis<input name="name" maxlength="80" required></label><label>Jenis bisnis<select name="category"><option>Cafe & Restaurant</option><option>Retail</option><option>Salon & Services</option><option>Other</option></select></label><label>Warna brand<input type="color" name="accent" value="#087f6c"></label><button class="primary">Buat workspace</button></form><p>Staf yang sudah diberi akses dapat memuat ulang workspace.</p><button id="checkmembership">Muat ulang akses</button><button id="onlogout">Keluar</button></section></main><footer class="site-powered">Powered by SUMS POS</footer>`;document.querySelector('#onboard').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await cloudAction(async()=>{state.current=await api.rpc('pos_create_business',{p_name:f.get('name').trim(),p_category:f.get('category'),p_accent:f.get('accent')});page='products'})};document.querySelector('#checkmembership').onclick=()=>refreshCloud();document.querySelector('#onlogout').onclick=async()=>{await api.logout();cloud=false;authScreen()}}
function staffForm(){const m=modal(`<h2>Kelola staf</h2><div>${(business().staffAccounts||[]).map(a=>`<div class="row"><span><b>${esc(a.name)}</b><br><small>${esc(a.username)}</small></span><span class="badge">${esc(business().members?.find(x=>x.user_id===a.user_id)?.role||'staff')}</span></div>`).join('')||'<p>Belum ada akun staf dengan username.</p>'}</div><h2 style="margin-top:20px">Tambah staf</h2><form><label>Nama lengkap<input name="name" required maxlength="80" autocomplete="off"></label><label>Username<input name="username" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9_.-]{3,32}" autocomplete="off" placeholder="contoh: aruna.kasir01"></label><label>Password<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label>Akses<select name="role"><option value="cashier">Kasir · pesanan & pembayaran</option>${business().restaurant_mode&&business().waiter_enabled?'<option value="waiter">Waiter · pesanan & cetak section</option>':''}</select></label><button class="primary">Buat akun staf</button></form><p>Username unik di seluruh SUMS POS. Staf langsung login tanpa email konfirmasi.</p>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('button');btn.disabled=true;try{if(await cloudAction(()=>api.createStaff({business_id:business().id,name:f.get('name'),username:f.get('username'),password:f.get('password'),role:f.get('role')}))){e.target.reset();m.close();toast('Akun staf dibuat. Staf dapat login menggunakan username.')}}finally{btn.disabled=false}}}
async function boot(){try{save()}catch{}if(api.getSession()){try{await api.verifySession();cloud=true;await refreshCloud();return}catch{await api.logout().catch(()=>{});cloud=false}}authScreen()}
// Recovery refresh is secondary to Realtime; the feed remains active on Back Office too.
setInterval(()=>{if(cloud&&!document.hidden)scheduleSync()},60000);

function categoryManager(){const b=business(),m=modal(`<h2>Kategori produk</h2><p>Kategori tersimpan untuk produk sekarang dan berikutnya.</p><div>${(b.categories||[]).map(c=>`<div class="row"><span>${esc(c.name)} ${c.active?'':'(nonaktif)'}</span><div class="actions"><button data-categoryedit="${c.id}">Edit</button><button class="danger" data-categorydelete="${c.id}" ${b.products.some(p=>p.category_id===c.id)?'disabled title="Category must be empty"':''}>Delete</button></div></div>`).join('')}</div><button id="addcategory">+ Kategori baru</button>`);m.querySelectorAll('[data-categorydelete]').forEach(el=>el.onclick=()=>{m.close();deleteCategoryForm(el.dataset.categorydelete)});m.querySelector('#addcategory').onclick=()=>{m.close();categoryForm()};m.querySelectorAll('[data-categoryedit]').forEach(el=>el.onclick=()=>{m.close();categoryForm(el.dataset.categoryedit)})}
function categoryForm(id){const c=business().categories?.find(c=>c.id===id)||{name:'',active:true},m=modal(`<h2>${id?'Edit kategori':'Kategori baru'}</h2><form><label>Nama kategori<input name="name" required maxlength="40" value="${esc(c.name)}"></label><label>Status<select name="active"><option value="true">Aktif</option><option value="false" ${c.active?'':'selected'}>Nonaktif</option></select></label><button class="primary">Simpan kategori</button></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),active=f.get('active')==='true';if(!name)return toast('Isi nama kategori');if(cloud){if(await cloudAction(()=>api.rpc('pos_save_category',{b:business().id,p_id:id||null,p_name:name,p_active:active})))m.close()}else if(mutate(()=>{const b=business();b.categories??=[];if(id){Object.assign(b.categories.find(c=>c.id===id),{name,active});b.products.filter(p=>p.category_id===id).forEach(p=>p.category=name)}else b.categories.push({id:crypto.randomUUID(),name,active});return true}))m.close()}}
function deviceKey(){return 'sums-pos-printer-'+(api.getSession()?.user?.id||'demo')+'-'+business().id+'-'+role}
function devicePrefs(){try{return JSON.parse(localStorage.getItem(deviceKey()))||{width:business().receipt_width||80,target:''}}catch{return {width:80,target:''}}}
function devicePrintForm(){const p=devicePrefs(),m=modal(`<h2>Printer ${role==='waiter'?'Waiter':'Kasir'}</h2><p>Pengaturan perangkat/browser ini. Printer fisik dipilih di dialog cetak sistem.</p><form><label>Ukuran kertas<select name="width"><option value="58" ${p.width===58?'selected':''}>58 mm</option><option value="80" ${p.width===80?'selected':''}>80 mm</option></select></label><label>Nama printer / perangkat<input name="target" maxlength="80" value="${esc(p.target)}" placeholder="Misalnya: Epson Kasir / Bluetooth Bar"></label><button class="primary">Simpan pengaturan</button></form><p>Belum menghubungkan Bluetooth secara langsung atau mengganti printer OS otomatis.</p>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);localStorage.setItem(deviceKey(),JSON.stringify({width:Number(f.get('width')),target:f.get('target')}));m.close();toast('Pengaturan printer perangkat tersimpan')}}
function businessPrintForm(){const b=business();let logo=b.logo_data||'',sections=structuredClone(b.print_sections||[]);const m=modal('');function redraw(){m.innerHTML=`<div class="modalhead"><h2>Logo & cetak bisnis</h2><button id="closemodal">✕</button></div><form><label>Logo PNG / JPEG / WebP · maksimal 200 KB<input type="file" id="logofile" accept="image/png,image/jpeg,image/webp"></label>${logo?`<img src="${esc(logo)}" alt="Logo bisnis" style="max-width:120px;max-height:70px"><button type="button" id="clearlogo">Hapus logo</button>`:''}<label>Lebar struk default<select id="receiptwidth"><option value="58" ${(b.receipt_width||80)===58?'selected':''}>58 mm</option><option value="80" ${(b.receipt_width||80)===80?'selected':''}>80 mm</option></select></label><h2>Section persiapan</h2><p>Kasir mencetak struk. Waiter mencetak item per kategori ke section Kitchen/Bar yang dipilih.</p>${sections.map((x,i)=>`<fieldset style="border:1px solid #ddd;border-radius:10px;padding:15px"><label>Section<input data-sectionname="${i}" value="${esc(x.name)}" maxlength="40" required></label><label>Nama printer<input data-sectiontarget="${i}" value="${esc(x.target||'')}" maxlength="80"></label><label>Ukuran<select data-sectionwidth="${i}"><option value="58" ${Number(x.width)===58?'selected':''}>58 mm</option><option value="80" ${Number(x.width)===80?'selected':''}>80 mm</option></select></label><div class="permissions">${(b.categories||[]).map(c=>`<label><input type="checkbox" data-sectioncat="${i}" value="${c.id}" ${x.categories.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}</div><button type="button" data-removesection="${i}">Hapus section</button></fieldset>`).join('')}<button type="button" id="addsection">+ Section printer</button><button class="primary">Simpan logo & section</button></form>`;m.querySelector('#closemodal').onclick=()=>m.close();m.querySelector('#clearlogo')?.addEventListener('click',()=>{capture();logo='';redraw()});m.querySelector('#logofile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>200000)return toast('Gunakan PNG/JPEG/WebP maksimal 200 KB');logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});capture();redraw()};m.querySelector('#addsection').onclick=()=>{capture();sections.push({name:'Section '+(sections.length+1),target:'',width:80,categories:[]});redraw()};m.querySelectorAll('[data-removesection]').forEach(el=>el.onclick=()=>{capture();sections.splice(Number(el.dataset.removesection),1);redraw()});m.querySelector('form').onsubmit=async e=>{e.preventDefault();capture();if(sections.some(x=>!x.name.trim()||!x.categories.length))return toast('Setiap section perlu nama dan kategori');if(cloud){if(await cloudAction(()=>api.rpc('pos_save_print_config',{b:b.id,p_logo:logo,p_width:b.receipt_width||80,p_sections:sections})))m.close()}else if(mutate(()=>{Object.assign(b,{logo_data:logo,print_sections:sections});return true}))m.close()}}function capture(){const width=m.querySelector('#receiptwidth');if(width)b.receipt_width=Number(width.value);sections.forEach((x,i)=>{x.name=m.querySelector(`[data-sectionname="${i}"]`).value;x.target=m.querySelector(`[data-sectiontarget="${i}"]`).value;x.width=Number(m.querySelector(`[data-sectionwidth="${i}"]`).value);x.categories=[...m.querySelectorAll(`[data-sectioncat="${i}"]:checked`)].map(el=>el.value)})}redraw()}
function printPicker(o){const sections=business().print_sections||[],m=modal(`<h2>Pilih dokumen cetak</h2>${role!=='waiter'?'<button id="printreceipt">Struk kasir · seluruh pembelanjaan</button>':''}<h2 style="margin-top:20px">Pesanan waiter</h2>${sections.map((x,i)=>`<div class="row"><span>${esc(x.name)}<br><small>${esc(x.target||'Pilih printer di dialog')} · ${x.width} mm</small></span><button data-printsection="${i}">Cetak section</button></div>`).join('')||'<p>Owner perlu mengatur section dan kategori di Pengaturan bisnis → Logo & cetak.</p>'}<p>Pilih printer yang sesuai pada dialog cetak untuk setiap section.</p>`);m.querySelector('#printreceipt')?.addEventListener('click',()=>{m.close();renderPrint(o)});m.querySelectorAll('[data-printsection]').forEach(el=>el.onclick=()=>{m.close();renderPrint(o,sections[Number(el.dataset.printsection)])})}
async function renderPrint(o,section){const b=business(),prefs=devicePrefs(),width=section?Number(section.width):prefs.width,lines=section?o.lines.filter(l=>section.categories.includes(l.category_id||b.products.find(p=>p.id===l.id)?.category_id)&&!l.voided_at):o.lines.filter(l=>!l.voided_at);if(!lines.length)return toast('Tidak ada item untuk section ini');document.querySelector('.receipt')?.remove();document.querySelector('#printstyle')?.remove();const style=document.createElement('style');style.id='printstyle';style.textContent=`@media print{@page{size:auto;margin:2mm}body>.receipt{width:${width-6}mm!important}.receipt img{max-width:100%;max-height:22mm;display:block;margin:0 auto}}`;document.head.append(style);const r=document.createElement('section');r.className='receipt';r.innerHTML=`${!section&&b.logo_data?`<img src="${esc(b.logo_data)}" alt="Logo ${esc(b.name)}">`:''}<h2>${esc(b.name)}</h2><p style="text-align:center">${section?esc(section.name)+(o.print_kind==='void'?' · VOID / CANCELLATION':' · PESANAN'):o.status==='paid'?'STRUK PEMBAYARAN':'TAGIHAN BELUM LUNAS'}<br>${esc(o.number)}<br>${new Date(o.createdAt).toLocaleString(locale())}</p><p>${esc(o.table||o.type)} · ${esc(o.guest_name||'')}<br>Pembuat: ${esc(o.created_by_name||'Belum tercatat')}</p>${lines.map(l=>`<div class="row"><span>${l.qty} × ${esc(l.name)}${l.item_note?'<br><small>'+esc(l.item_note)+'</small>':''}</span>${section?'':`<span>${money(l.price*l.qty)}</span>`}</div>`).join('')}${section?'':`${o.discount_amount?`<div class="row"><span>Subtotal</span><span>${money(o.subtotal)}</span></div><div class="row"><span>${esc(o.discount_name||'Diskon')}</span><span>−${money(o.discount_amount)}</span></div>`:''}<div class="row"><span>Service ${(o.service_bps||0)/100}%</span><span>${money(o.service_amount||0)}</span></div><div class="row"><span>Tax ${(o.tax_bps||0)/100}%</span><span>${money(o.tax_amount||0)}</span></div><div class="row"><b>Total</b><b>${money(o.total)}</b></div>${o.status==='paid'&&(business().refunds||[]).some(r=>r.order_id===o.id&&r.status==='completed')?`<p>Refund tercatat: ${money((business().refunds||[]).filter(r=>r.order_id===o.id&&r.status==='completed').reduce((n,r)=>n+r.amount,0))}<br>Sisa pembayaran setelah refund: ${money(o.total-(business().refunds||[]).filter(r=>r.order_id===o.id&&r.status==='completed').reduce((n,r)=>n+r.amount,0))}</p>`:''}${o.status==='paid'?`<p>Kasir: ${esc([...new Set((o.payments||[]).map(p=>p.paid_by_name).filter(Boolean))].join(', ')||'Belum tercatat')}<br>${(o.payments||[]).map(p=>`${esc(paymentMethods[p.method]||p.method)} ${money(p.amount)}`).join('<br>')}${(o.payments||[]).some(p=>p.method==='cash')?`<br>Tunai diterima ${money(o.tendered)}<br>Kembali ${money(o.change)}`:''}</p>`:''}`}<p>${esc(o.note)}</p>${section?'':'<p style="text-align:center">Terima kasih</p>'}<p class="receipt-powered" style="text-align:center">Powered by SUMS POS</p>`;localize(r);document.body.append(r);await Promise.all([...r.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));window.print()}

function legacyPaymentForm(id){const o=business().orders.find(o=>o.id===id),rules=(business().discounts||[]).filter(d=>validDiscount(d,o.subtotal??o.total));const m=modal(`<h2>Load & bayar ${esc(o.number)}</h2><p>${esc(o.table||o.type)} · ${esc(o.guest_name||'')}</p>${o.lines.map(l=>`<div class="row"><span>${l.qty} × ${esc(l.name)}<small>${esc(l.item_note||'')}</small></span><span>${money(l.price*l.qty)}</span></div>`).join('')}<form><label>Diskon berlaku<select name="discount"><option value="">Tanpa diskon</option>${rules.map(d=>`<option value="${d.id}">${esc(d.name)} · −${money(discountAmount(d,o.subtotal))}</option>`).join('')}</select></label><p id="pay-total">Total ${money(o.total)}</p><label>Uang tunai diterima<input name="tendered" type="number" min="${o.total}" max="1000000000000" step="1" required value="${o.total}"></label><button class="primary">Catat pembayaran tunai</button></form>`);m.querySelector('[name=discount]').onchange=e=>{const d=rules.find(d=>d.id===e.target.value),net=(o.subtotal??o.total)-discountAmount(d,o.subtotal??o.total);m.querySelector('#pay-total').textContent='Total '+money(net);const input=m.querySelector('[name=tendered]');input.min=net;input.value=net};m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(mutate(()=>payOrder(business(),o.id,'cash',Number(f.get('tendered')),role)))m.close()}}
function cancelForm(id){const o=business().orders.find(o=>o.id===id);if(!o||o.status!=='open')return toast('Pesanan tidak aktif');const m=modal(`<h2>Hapus / Void</h2><p data-usertext>${esc(o.number)} · ${esc(o.guest_name||o.table||o.type)} · ${money(o.total)}</p><p>Pesanan yang dibatalkan tercatat pada laporan Cancelled.</p><p>Stok dikembalikan dan meja tersedia kembali setelah berhasil.</p><form>${cloud?'<label>PIN pembatalan<input type="password" name="pin" required inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="off"></label>':''}<label>Jenis alasan<select id="void-reason-type"><option value="">Pilih alasan</option><option value="customer">Customer membatalkan pesanan</option><option value="stock">Bahan baku habis</option><option value="other">Alasan lainnya</option></select></label><label>Catatan pembatalan (wajib)<textarea name="reason" required minlength="3" maxlength="300"></textarea></label><p id="cancel-error" role="status"></p><button class="danger">Konfirmasi Void</button></form>`);m.querySelector('#void-reason-type').onchange=e=>{const input=m.querySelector('[name=reason]');input.value=({customer:tr('Customer membatalkan pesanan'),stock:tr('Bahan baku habis'),other:''})[e.target.value]||'';input.focus()};m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(cloud){let result;const saved=await cloudAction(async()=>{result=await api.rpc('pos_cancel_order_v2',{b:business().id,p_order:id,p_pin:f.get('pin'),p_reason:f.get('reason')})});if(saved&&result.ok){m.close();toast('Pesanan dibatalkan dan tercatat pada laporan Cancel / Void')}else if(saved){m.querySelector('#cancel-error').textContent=result.error;m.querySelector('[name=pin]').value='';toast(result.error)}}else if(mutate(()=>cancelOrder(business(),id,role)))m.close()}}

function paymentForm(id){const o=business().orders.find(o=>o.id===id);if(cloud)checkout.pay(o);else legacyPaymentForm(id)}

function exportPayments(){const rows=[['Pesanan','Waktu bayar','Pembuat pesanan','Kasir','Metode','Nominal IDR','Referensi'],...selectedSales().flatMap(o=>(o.payments||[]).map(p=>[o.number,o.paidAt,o.created_by_name||'',p.paid_by_name||'',paymentMethods[p.method]||p.method,p.amount,p.reference||'']))];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='sums-pos-payments.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
setInterval(()=>document.querySelectorAll('[data-table-clock]').forEach(el=>{el.textContent=Math.max(0,Math.floor((Date.now()-Date.parse(el.dataset.tableClock))/60000))+' menit'}),30000);

function cancelReport(){const list=cancelledInPeriod(business().orders,reportDays);return `<section class="card" style="margin-top:22px"><h2>Laporan void / cancel</h2><p>${list.length} bill dibatalkan · nilai bill ${money(list.reduce((s,o)=>s+o.total,0))}. Tidak dihitung sebagai penjualan atau pembayaran.</p><div class="tablewrap"><table><thead><tr><th>BILL</th><th>WAKTU BATAL</th><th>PEMBUAT</th><th>DIBATALKAN OLEH</th><th>ALASAN</th><th>NILAI BILL</th></tr></thead><tbody>${list.map(o=>`<tr><td>${esc(o.number)}</td><td>${new Date(o.cancelled_at).toLocaleString(locale())}</td><td>${esc(o.created_by_name||'Belum tercatat')}</td><td>${esc(o.cancelled_by_name||'Belum tercatat')}</td><td>${esc(o.cancel_reason||'Belum tercatat')}</td><td>${money(o.total)}</td></tr>`).join('')||'<tr><td colspan="6">Tidak ada pembatalan pada periode ini.</td></tr>'}</tbody></table></div><button id="cancel-csv">Export void / cancel</button></section>${itemVoidReport()}`}
function exportCancels(){const rows=[['Bill','Waktu batal','Pembuat','Dibatalkan oleh','Alasan','Nilai bill IDR'],...cancelledInPeriod(business().orders,reportDays).map(o=>[o.number,o.cancelled_at,o.created_by_name,o.cancelled_by_name,o.cancel_reason,o.total])];downloadCsv(rows,'sums-pos-cancellations.csv')}
function downloadCsv(rows,name){const csv=rows.map(row=>row.map(v=>{const value=String(v??'');return '"'+(/^[=+@-]/.test(value)?"'":'')+value.replace(/"/g,'""')+'"'}).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function variantPicker(p,rect){const variants=business().products.filter(v=>v.parent_product_id===p.id&&v.active),m=modal(`<h2>${esc(p.name)} · pilih varian</h2>${variants.map(v=>`<div class="row"><span><b>${esc(v.variant_label)}</b><small>${v.stock} tersedia · ${money(v.price)}</small></span><button data-pick-variant="${v.id}" ${v.stock===0?'disabled':''}>Tambah</button></div>`).join('')}`);m.querySelectorAll('[data-pick-variant]').forEach(el=>el.onclick=()=>{const v=variants.find(v=>v.id===el.dataset.pickVariant),l=cart.find(l=>l.id===v.id);if((l?.qty||0)>=v.stock)return toast('Stok varian tidak cukup');if(l)l.qty++;else cart.push({id:v.id,name:v.name,price:v.price,qty:1});m.close();render();flyToBasket(rect,p.photo_data,p.icon)})}
function variantForm(id){const p=business().products.find(p=>p.id===id);let rows=business().products.filter(v=>v.parent_product_id===id).map(v=>({id:v.id,name:v.variant_label,price:v.price,stock:v.stock,active:v.active}));const m=modal('');function capture(){m.querySelectorAll('[data-variant-row]').forEach(el=>{const i=Number(el.dataset.variantRow);rows[i]={...rows[i],name:el.querySelector('[name=name]').value,price:Number(el.querySelector('[name=price]').value),stock:Number(el.querySelector('[name=stock]').value),active:el.querySelector('[name=active]').checked}})}function draw(){m.innerHTML=`<div class="modalhead"><h2>Varian · ${esc(p.name)}</h2><button id="closemodal">✕</button></div><p>Setiap varian memiliki harga dan stok sendiri. HPP mengikuti produk utama.</p><form>${rows.map((v,i)=>`<fieldset class="payment-part" data-variant-row="${i}"><label>Nama varian<input name="name" maxlength="40" required value="${esc(v.name)}" placeholder="Regular / Large"></label><label>Harga jual<input name="price" type="number" min="1" max="100000000" step="1" required value="${v.price}"></label><label>Stok varian<input name="stock" type="number" min="0" max="1000000" step="1" required value="${v.stock}"></label><label><input name="active" type="checkbox" ${v.active?'checked':''}> Aktif</label></fieldset>`).join('')}<button type="button" id="add-variant" ${rows.length>=30?'disabled':''}>+ Varian</button><button class="primary">Simpan varian & harga</button></form>`;m.querySelector('#closemodal').onclick=()=>m.close();m.querySelector('#add-variant').onclick=()=>{capture();rows.push({id:null,name:'',price:p.price,stock:0,active:true});draw()};m.querySelector('form').onsubmit=async e=>{e.preventDefault();capture();if(await cloudAction(()=>api.rpc('pos_save_variants',{b:business().id,p_product:p.id,p_variants:rows})))m.close()}}draw()}

async function submitWaiterOrder(args){if(busy)return;busy=true;const m=modal('<div class="order-submit-status" role="status" aria-live="polite"><div class="submit-spinner" aria-hidden="true"></div><h2>Mengirim pesanan…</h2><p>Mohon tunggu sebentar.</p></div>');m.classList.add('submit-dialog');m.querySelector('#closemodal').hidden=true;const prevent=e=>{if(busy)e.preventDefault()};m.addEventListener('cancel',prevent);let accepted=false;try{await api.rpc('pos_place_order_v4',args);accepted=true;cart=[];resetGuest();requestId=crypto.randomUUID();page='tables';render();m.innerHTML='<div class="order-submit-status" role="status" aria-live="polite"><div class="submit-check" aria-hidden="true">✓</div><h2>Pesanan sudah terkirim</h2><p>Pesanan tersimpan untuk kasir dan antrean section.<br>Kembali ke pemilihan meja…</p></div>';await Promise.all([refreshCloud(),new Promise(resolve=>setTimeout(resolve,1100))]);m.close()}catch(err){m.innerHTML=`<div class="order-submit-status" role="alert"><h2>${accepted?'Pesanan sudah tersimpan':'Pesanan belum terkonfirmasi'}</h2><p>${esc(err.message)}</p><p>${accepted?'Muat ulang untuk melihat pesanan.':'Basket tetap tersimpan. Coba kirim ulang dengan request yang sama.'}</p><button id="submit-back" class="primary">Kembali</button></div>`;m.querySelector('#submit-back').onclick=()=>{m.close();render()}}finally{busy=false;m.classList.remove('submit-dialog');m.removeEventListener('cancel',prevent);render()}}

function connectionText(){return !navigator.onLine?'Offline · transaksi memerlukan internet':liveStatus==='live'?'Realtime terhubung':liveStatus==='connecting'?'Menghubungkan Realtime…':'Realtime terputus · sinkronisasi cadangan aktif'}
function updateConnection(){document.querySelectorAll('[data-live-status]').forEach(el=>el.textContent=connectionText());document.body.classList.toggle('pos-offline',!navigator.onLine)}
function stopLive(){liveChannel?.close();liveChannel=null;liveKey='';clearTimeout(syncTimer);pendingSync=false}
function startLive(){if(!cloud||!state.current||!api.getSession())return;const key=api.getSession().user.id+':'+state.current;if(liveKey===key)return;stopLive();liveKey=key;liveChannel=workspaceRealtime({url:supabaseUrl,key:publishableKey,business:state.current,getToken:api.accessToken,onChange:scheduleSync,onStatus:value=>{liveStatus=value;updateConnection()}})}
function scheduleSync(){if(!cloud)return;pendingSync=true;clearTimeout(syncTimer);syncTimer=setTimeout(syncWorkspace,250)}
async function syncWorkspace(){if(!pendingSync||!cloud||!state.current||!navigator.onLine)return;if(busy||syncFlight||document.hidden||document.querySelector('#modal').open){syncTimer=setTimeout(syncWorkspace,1000);return}syncFlight=true;pendingSync=false;const id=state.current;try{const [data,list]=await Promise.all([api.loadBusiness(id),api.loadBusinesses()]);if(!cloud||state.current!==id)return;if(!list.some(b=>b.id===id)){await refreshCloud();return}const membership=list.find(b=>b.id===id).membership;business().membership=membership;role=membership.role;if(['cashier','waiter'].includes(role)){surface='pos';const u=new URL(location.href);u.searchParams.set('app','pos');history.replaceState(null,'',u)}const changed=JSON.stringify(data)!==cloudStamp;Object.assign(business(),data);cloudStamp=JSON.stringify(data);if(changed&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();updateConnection()}catch{liveStatus='degraded';updateConnection()}finally{syncFlight=false;if(pendingSync)syncTimer=setTimeout(syncWorkspace,250)}}
window.addEventListener('online',()=>{startLive();scheduleSync();updateConnection()});window.addEventListener('offline',updateConnection);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&cloud){startLive();scheduleSync()}});lockPOSZoom(()=>document.body.classList.contains('pos-app-shell'));window.addEventListener('pos-install-change',()=>{const el=document.querySelector('#pos-install');if(el)el.textContent=installAvailable()?'Install sekarang':'Pasang aplikasi'});

function languageSettings(){return `<section class="card language-card"><h2>Bahasa</h2><label>Bahasa aplikasi<select id="app-language"><option value="en" ${getLanguage()==='en'?'selected':''}>English</option><option value="id" ${getLanguage()==='id'?'selected':''}>Indonesia</option></select></label></section>`}
function deviceSettings(){return `<div class="pos-device-settings"><section class="card"><h2>Pengaturan aplikasi</h2><div class="settings-actions"><button id="deviceprint">Printer</button><button id="pos-fullscreen">Fullscreen</button><button id="pos-install">Pasang aplikasi</button><button id="refresh-pos">Muat ulang</button>${role==='owner'?'<button id="office-pos">Buka Back Office</button>':''}</div></section>${languageSettings()}${cloud&&business().restaurant_mode?restaurant.queue():''}<section class="card"><h2>Koneksi</h2><p data-live-status>${connectionText()}</p></section><section class="card"><h2>Akun</h2><p>${esc(role.toUpperCase())}</p><button id="logout-pos">Keluar</button></section></div>`}

function voidLineForm(orderId,lineId){const o=business().orders.find(o=>o.id===orderId),l=o?.lines.find(l=>l.line_id===lineId);if(!l||l.voided_at||o.status!=='open')return;const m=modal(`<h2>Hapus item</h2><p data-usertext>${esc(o.number)} · ${l.qty} × ${esc(l.name)}</p><form><label>PIN pembatalan<input type="password" name="pin" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off"></label><label>Alasan pembatalan<textarea name="reason" required minlength="3" maxlength="300"></textarea></label><p id="line-void-error" role="status"></p><button class="danger">Konfirmasi Void</button></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);let result;if(await cloudAction(async()=>{result=await api.rpc('pos_void_line',{b:business().id,p_order:orderId,p_line:lineId,p_pin:f.get('pin'),p_reason:f.get('reason')})})){if(result.ok){m.close();orderDetails(orderId)}else{m.querySelector('#line-void-error').textContent=result.error;m.querySelector('[name=pin]').value=''}}}}
function itemVoidRows(){const start=new Date();if(reportDays===1)start.setHours(0,0,0,0);else start.setTime(Date.now()-reportDays*86400000);return business().orders.flatMap(o=>o.lines.filter(l=>l.voided_at&&Date.parse(l.voided_at)>=start.getTime()).map(l=>({o,l})));}
function itemVoidReport(){const rows=itemVoidRows();return `<section class="card" style="margin-top:18px"><h2>Item void report</h2><p>Item cancellations are listed separately from whole-bill cancellations.</p><div class="tablewrap"><table><thead><tr><th>BILL</th><th>Item</th><th>Qty</th><th>WAKTU BATAL</th><th>DIBATALKAN OLEH</th><th>ALASAN</th><th>Amount IDR</th></tr></thead><tbody>${rows.map(({o,l})=>`<tr><td>${esc(o.number)}</td><td data-usertext>${esc(l.name)}</td><td>${l.qty}</td><td>${new Date(l.voided_at).toLocaleString(locale())}</td><td data-usertext>${esc(l.voided_by_name)}</td><td data-usertext>${esc(l.void_reason)}</td><td>${money(l.void_amount)}</td></tr>`).join('')||'<tr><td colspan="7">No voided items.</td></tr>'}</tbody></table></div><button id="item-void-export">Export item voids CSV</button></section>`}

function navIcon(p){const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',orders:'M7 3h10v18H7zM10 8h4M10 12h4M10 16h4',products:'M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5M12 12v9',reports:'M4 20h16M7 17v-6M12 17V4M17 17V8',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M6 6l2 2M16 16l2 2M6 18l2-2M16 8l2-2M8 12a4 4 0 1 0 8 0 4 4 0 1 0-8 0',outlets:'M3 10h18M5 10v11h14V10M3 10l2-7h14l2 7M9 21v-7h6v7'};return `<svg class="nav-icon" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[p]||paths.orders}"/></svg>`}

function deleteProductForm(id){const p=business().products.find(p=>p.id===id);if(!p)return;const m=modal(`<h2>Delete product?</h2><p data-usertext>${esc(p.name)}</p><p>This removes the product and its variants from the catalogue. Existing orders, stock history and reports are preserved.</p><button class="danger" id="confirm-delete-product">Delete product</button>`);m.querySelector('#confirm-delete-product').onclick=async()=>{if(cloud){if(await cloudAction(()=>api.rpc('pos_delete_product',{b:business().id,p_product:id})))m.close();}else if(mutate(()=>{if(role!=='owner')throw Error('Akses ditolak');business().products=business().products.filter(x=>x.id!==id&&x.parent_product_id!==id);return true}))m.close();};}
function deleteCategoryForm(id){const c=business().categories.find(c=>c.id===id);if(!c)return;if(business().products.some(p=>p.category_id===id))return toast('Category must be empty');const m=modal(`<h2>Delete empty category?</h2><p data-usertext>${esc(c.name)}</p><p>Existing order reports keep their original category name.</p><button class="danger" id="confirm-delete-category">Delete category</button>`);m.querySelector('#confirm-delete-category').onclick=async()=>{if(cloud){if(await cloudAction(()=>api.rpc('pos_delete_category',{b:business().id,p_category:id})))m.close();}else if(mutate(()=>{if(role!=='owner')throw Error('Akses ditolak');business().categories=business().categories.filter(c=>c.id!==id);return true}))m.close();};}
